// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Set initial owner to caller
        vm.prank(address(0)); // owner defaults to address(0), so we can call transferOwnership
        c.transferOwnership(caller);
        // Now caller is owner, call owned()
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(success && c.owner() == caller);
    }
}

